INSERT INTO `knowledge_posts` VALUES (1,'test','test',NULL,NULL,NULL,'test',NULL,1,'2026-03-12 21:31:18',0,1,'2026-03-13 04:31:18','2026-09-29 23:01:46',1,NULL,NULL),(2,'6 วิธีเพิ่มความอยากอาหารให้ผู้สูงอายุ','nutrition-60plus-01',NULL,'อินโฟกราฟิกความรู้ด้านอาหารและโภชนาการสำหรับผู้สูงอายุ','/knowledge-media/nutrition-01.webp','กินดีวัย 60+','ผู้สูงอายุ,โภชนาการ,อินโฟกราฟิก',1,NULL,1,1,'2026-09-29 03:51:50','2026-09-29 03:51:50',0,'/knowledge-media/nutrition-01.pdf','pdf'),(3,'อาหารแลกเปลี่ยน หมวดข้าวและแป้ง','nutrition-60plus-02',NULL,'อินโฟกราฟิกความรู้ด้านอาหารและโภชนาการสำหรับผู้สูงอายุ','/knowledge-media/nutrition-02.webp','กินดีวัย 60+','ผู้สูงอายุ,โภชนาการ,อินโฟกราฟิก',1,NULL,2,1,'2026-09-29 03:51:50','2026-09-29 03:51:50',0,'/knowledge-media/nutrition-02.pdf','pdf'),(4,'อาหารแลกเปลี่ยน หมวดเนื้อสัตว์','nutrition-60plus-03',NULL,'อินโฟกราฟิกความรู้ด้านอาหารและโภชนาการสำหรับผู้สูงอายุ','/knowledge-media/nutrition-03.webp','กินดีวัย 60+','ผู้สูงอายุ,โภชนาการ,อินโฟกราฟิก',1,NULL,3,1,'2026-09-29 03:51:50','2026-09-29 03:51:50',0,'/knowledge-media/nutrition-03.pdf','pdf'),(5,'อาหารแลกเปลี่ยน หมวดผัก','nutrition-60plus-04',NULL,'อินโฟกราฟิกความรู้ด้านอาหารและโภชนาการสำหรับผู้สูงอายุ','/knowledge-media/nutrition-04.webp','กินดีวัย 60+','ผู้สูงอายุ,โภชนาการ,อินโฟกราฟิก',1,NULL,4,1,'2026-09-29 03:51:50','2026-09-29 03:51:50',0,'/knowledge-media/nutrition-04.pdf','pdf'),(6,'อาหารแลกเปลี่ยน หมวดผลไม้','nutrition-60plus-05',NULL,'อินโฟกราฟิกความรู้ด้านอาหารและโภชนาการสำหรับผู้สูงอายุ','/knowledge-media/nutrition-05.webp','กินดีวัย 60+','ผู้สูงอายุ,โภชนาการ,อินโฟกราฟิก',1,NULL,5,1,'2026-09-29 03:51:50','2026-09-29 03:51:50',0,'/knowledge-media/nutrition-05.pdf','pdf'),(7,'อาหารแลกเปลี่ยน หมวดนม','nutrition-60plus-06',NULL,'อินโฟกราฟิกความรู้ด้านอาหารและโภชนาการสำหรับผู้สูงอายุ','/knowledge-media/nutrition-06.webp','กินดีวัย 60+','ผู้สูงอายุ,โภชนาการ,อินโฟกราฟิก',1,NULL,6,1,'2026-09-29 03:51:50','2026-09-29 03:51:50',0,'/knowledge-media/nutrition-06.pdf','pdf'),(8,'อาหารแ