--
-- Table structure for table `mna_responses`
--

DROP TABLE IF EXISTS `mna_responses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `mna_responses` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `visit_id` int(11) NOT NULL,
  `scoring_version_id` int(11) NOT NULL,
  `q1_food_intake_decline` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_s1` decimal(10,2) DEFAULT NULL,
  `q2_weight_loss` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_s2` decimal(10,2) DEFAULT NULL,
  `q3_mobility` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_s3` decimal(10,2) DEFAULT NULL,
  `q4_stress_illness` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_s4` decimal(10,2) DEFAULT NULL,
  `q5_neuropsychological` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_s5` decimal(10,2) DEFAULT NULL,
  `q6_bmi` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_s6` decimal(10,2) DEFAULT NULL,
  `q7_calf_circumference` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_s7` decimal(10,2) DEFAULT NULL,
  `mna_screen_total` decimal(10,2) DEFAULT NULL,
  `mna_screen_category` tinyint(1) DEFAULT NULL COMMENT '1=Normal(12-14), 2=ModMal(8-11), 3=Mal(0-7)',
  `q8_independent_living` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_a1` decimal(10,2) DEFAULT NULL,
  `q9_medications` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_a2` decimal(10,2) DEFAULT NULL,
  `q10_pressure_sores` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_a3` decimal(10,2) DEFAULT NULL,
  `q11_full_meals` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_a4` decimal(10,2) DEFAULT NULL,
  `q12_protein_consumption` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_a5` decimal(10,2) DEFAULT NULL,
  `q13_fruits_vegetables` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_a6` decimal(10,2) DEFAULT NULL,
  `q14_fluid_intake` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_a7` decimal(10,2) DEFAULT NULL,
  `q15_eating_independence` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_a8` decimal(10,2) DEFAULT NULL,
  `q16_self_nutrition` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_a9` decimal(10,2) DEFAULT NULL,
  `q17_health_comparison` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_a10` decimal(10,2) DEFAULT NULL,
  `q18_mid_arm_circumference` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_a11` decimal(10,2) DEFAULT NULL,
  `q19_calf_circumference_assess` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mna_a12` decimal(10,2) DEFAULT NULL COMMENT 'mna_a12: CC score 0/2',
  `mac_cm` decimal(5,2) DEFAULT NULL COMMENT 'MAC: เส้นรอบวงแขน (cm)',
  `cc_cm` decimal(5,2) DEFAULT NULL COMMENT 'CC: เส้นรอบวงน่อง (cm)',
  `mna_ass_total` decimal(10,2) DEFAULT NULL,
  `mna_total` decimal(10,2) DEFAULT NULL,
  `mna_total_category` tinyint(1) DEFAULT NULL COMMENT '1=Normal(24-30), 2=ModMal(17-23.5), 3=Mal(<17)',
  `result_category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `entry_mode` enum('STAFF','SELF') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `ref_risk24` tinyint(1) DEFAULT NULL COMMENT '1 ถ้า mna_total < 24',
  `ref_mal17` tinyint(1) DEFAULT NULL COMMENT '1 ถ้า mna_total < 17',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_visit_id` (`visit_id`),
  KEY `idx_result_category` (`result_category`),
  KEY `idx_created_by` (`created_by`),
  KEY `fk_mna_scoring_version` (`scoring_version_id`),
  CONSTRAINT `fk_mna_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_mna_scoring_version` FOREIGN KEY (`scoring_version_id`) REFERENCES `scoring_rule_versions` (`id`),
  CONSTRAINT `fk_mna_visit` FOREIGN KEY (`visit_id`) REFERENCES `visits` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=210 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `mna_responses`
--

